<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{NButton,NForm,NFormItem,NInput,NInputNumber,NModal,NSelect,NTag,useMessage}from'naive-ui';import{api}from'../api';const route=useRoute(),message=useMessage(),rows=ref<any[]>([]),show=ref(false),assetFor=ref<any>(null),sourceFor=ref<any>(null),form=reactive<any>({version:'',channel:1,title:'',changelog:'',min_required_version:''}),asset=reactive<any>({name:'',file_name:'',os:'windows',arch:'amd64',kind:1,size:0,sha256:''}),source=reactive<any>({name:'官方下载',source_type:2,external_url:'',extract_code:'',priority:0,is_enabled:true});async function load(){const x:any=await api.get(`/apps/${route.params.id}/releases`);rows.value=x.list}async function addRelease(){await api.post(`/apps/${route.params.id}/releases`,form);show.value=false;Object.assign(form,{version:'',channel:1,title:'',changelog:'',min_required_version:''});load()}async function publish(id:number){try{await api.post(`/releases/${id}/publish`);message.success('版本已发布');load()}catch(e:any){message.error(e.message)}}async function addAsset(){const x:any=await api.post(`/releases/${assetFor.value.id}/assets`,asset);assetFor.value=null;sourceFor.value=x;Object.assign(source,{name:'官方下载',source_type:2,external_url:'',extract_code:'',priority:0,is_enabled:true});load()}async function addSource(){await api.post(`/assets/${sourceFor.value.id}/sources`,source);sourceFor.value=null;load()}onMounted(load)</script>
<template><div class="page-head"><div><h1>版本与下载</h1><span style="color:#8b93a1">发布前，每个文件必须至少有一个启用的下载源</span></div><n-button type="primary" @click="show=true">新建版本</n-button></div><div class="panel"><div v-for="r in rows" :key="r.id" class="release"><div style="display:flex;justify-content:space-between"><div><h3 style="margin:0">v{{r.version}} <n-tag size="small">{{['','stable','beta','alpha'][r.channel]}}</n-tag></h3><span style="color:#8b93a1">{{r.title||'未填写标题'}}</span></div><div><n-button size="small" @click="assetFor=r">添加文件</n-button> <n-button size="small" type="primary" :disabled="r.status===1" @click="publish(r.id)">{{r.status===1?'已发布':'发布版本'}}</n-button></div></div><p>{{r.changelog}}</p><div v-for="a in r.assets" :key="a.id" class="asset-row"><b>{{a.name}}</b> · {{a.os}}/{{a.arch}} · {{a.file_name}}<n-button text type="primary" style="float:right" @click="sourceFor=a">添加来源</n-button><div v-if="a.sources?.length" style="margin-top:5px;color:#6b7280">来源：{{a.sources.map((s:any)=>s.name).join('、')}}</div></div></div><div v-if="!rows.length" style="padding:40px;text-align:center;color:#8b93a1">还没有版本，先创建一个草稿版本。</div></div>
<n-modal v-model:show="show" preset="card" title="新建版本" style="max-width:620px"><n-form label-placement="top"><div class="form-grid"><n-form-item label="版本号"><n-input v-model:value="form.version" placeholder="1.0.0"/></n-form-item><n-form-item label="渠道"><n-select v-model:value="form.channel" :options="[{label:'stable',value:1},{label:'beta',value:2},{label:'alpha',value:3}]"/></n-form-item><n-form-item class="wide" label="标题"><n-input v-model:value="form.title"/></n-form-item><n-form-item class="wide" label="更新日志（Markdown）"><n-input v-model:value="form.changelog" type="textarea" :rows="7"/></n-form-item><n-form-item label="强制更新阈值"><n-input v-model:value="form.min_required_version"/></n-form-item></div><n-button type="primary" @click="addRelease">保存草稿</n-button></n-form></n-modal>
<n-modal :show="!!assetFor" preset="card" title="添加版本文件" style="max-width:660px" @update:show="v=>{if(!v)assetFor=null}"><n-form label-placement="top"><div class="form-grid"><n-form-item label="显示名称"><n-input v-model:value="asset.name"/></n-form-item><n-form-item label="文件名"><n-input v-model:value="asset.file_name"/></n-form-item><n-form-item label="系统"><n-select v-model:value="asset.os" :options="['windows','macos','linux','android','ios','any'].map(x=>({label:x,value:x}))"/></n-form-item><n-form-item label="架构"><n-select v-model:value="asset.arch" :options="['amd64','arm64','universal','any'].map(x=>({label:x,value:x}))"/></n-form-item><n-form-item label="大小（字节）"><n-input-number v-model:value="asset.size" style="width:100%"/></n-form-item><n-form-item label="SHA256"><n-input v-model:value="asset.sha256"/></n-form-item></div><n-button type="primary" @click="addAsset">添加并配置来源</n-button></n-form></n-modal>
<n-modal :show="!!sourceFor" preset="card" title="添加下载来源" style="max-width:620px" @update:show="v=>{if(!v)sourceFor=null}"><n-form label-placement="top"><n-form-item label="来源类型"><n-select v-model:value="source.source_type" :options="[{label:'外链 / 网盘',value:2},{label:'托管对象',value:1}]"/></n-form-item><n-form-item label="显示名称"><n-input v-model:value="source.name"/></n-form-item><template v-if="source.source_type===2"><n-form-item label="外链 URL"><n-input v-model:value="source.external_url"/></n-form-item><n-form-item label="提取码"><n-input v-model:value="source.extract_code"/></n-form-item></template><template v-else><n-form-item label="存储 ID"><n-input-number v-model:value="source.storage_id"/></n-form-item><n-form-item label="对象键"><n-input v-model:value="source.object_key" placeholder="app/version/file.exe"/></n-form-item></template><n-button type="primary" @click="addSource">保存来源</n-button></n-form></n-modal></template>

